function cbGroup(name){
  if(name.startsWith('Vermis')) return 'vermis';
  const l=name.replace(/^(Left|Right)_/,'');
  if(l==='I_IV'||l==='V') return 'ant'; if(l==='VI') return 'vi'; if(l.startsWith('Crus')) return 'crus';
  if(l==='VIIb') return 'viib'; if(l.startsWith('VIII')) return 'viii'; if(l==='IX') return 'ix'; return 'x';
}

